import fs from 'node:fs';
import path from 'node:path';

// Minimal ZIP (store-only) implementation. It intentionally avoids shelling out to
// zip/unzip so .agyh works on Linux, macOS and Windows without extra dependencies.
const CRC_TABLE=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;t[n]=c>>>0;}return t;})();
export function crc32(buf){let c=0xffffffff;for(const b of buf)c=CRC_TABLE[(c^b)&0xff]^(c>>>8);return (c^0xffffffff)>>>0;}
function u16(n){const b=Buffer.alloc(2);b.writeUInt16LE(n);return b;}function u32(n){const b=Buffer.alloc(4);b.writeUInt32LE(n>>>0);return b;}
function safeName(name){name=String(name).replaceAll('\\','/');if(!name||name.startsWith('/')||/^[A-Za-z]:\//.test(name)||name.split('/').some(x=>x==='..'||x===''))throw Error('unsafe archive path: '+name);return name;}
export function createZip(entries){let offset=0;const locals=[],central=[];for(const item of entries){const name=safeName(item.name),nb=Buffer.from(name),data=Buffer.isBuffer(item.data)?item.data:Buffer.from(String(item.data));const crc=crc32(data);const local=Buffer.concat([u32(0x04034b50),u16(20),u16(0x800),u16(0),u16(0),u16(0),u32(crc),u32(data.length),u32(data.length),u16(nb.length),u16(0),nb,data]);locals.push(local);const cd=Buffer.concat([u32(0x02014b50),u16(20),u16(20),u16(0x800),u16(0),u16(0),u16(0),u32(crc),u32(data.length),u32(data.length),u16(nb.length),u16(0),u16(0),u16(0),u16(0),u32(0),u32(offset),nb]);central.push(cd);offset+=local.length;}const csize=central.reduce((n,b)=>n+b.length,0),eocd=Buffer.concat([u32(0x06054b50),u16(0),u16(0),u16(entries.length),u16(entries.length),u32(csize),u32(offset),u16(0)]);return Buffer.concat([...locals,...central,eocd]);}
export function readZip(buffer,{maxFiles=256,maxBytes=32*1024*1024}={}){if(!Buffer.isBuffer(buffer))buffer=Buffer.from(buffer);if(buffer.length>maxBytes)throw Error('archive exceeds size limit');const sig=Buffer.from([0x50,0x4b,0x05,0x06]);const eocd=buffer.lastIndexOf(sig);if(eocd<0)throw Error('invalid zip: EOCD missing');const count=buffer.readUInt16LE(eocd+10),cdOffset=buffer.readUInt32LE(eocd+16);if(count>maxFiles)throw Error('archive file count exceeds limit');let pos=cdOffset,total=0;const out=[];for(let i=0;i<count;i++){if(buffer.readUInt32LE(pos)!==0x02014b50)throw Error('invalid central directory');const method=buffer.readUInt16LE(pos+10),crc=buffer.readUInt32LE(pos+16),compressed=buffer.readUInt32LE(pos+20),size=buffer.readUInt32LE(pos+24),nameLen=buffer.readUInt16LE(pos+28),extraLen=buffer.readUInt16LE(pos+30),commentLen=buffer.readUInt16LE(pos+32),localOffset=buffer.readUInt32LE(pos+42),name=safeName(buffer.subarray(pos+46,pos+46+nameLen).toString('utf8'));if(method!==0||compressed!==size)throw Error('unsupported compressed entry: '+name);if(buffer.readUInt32LE(localOffset)!==0x04034b50)throw Error('invalid local header');const ln=buffer.readUInt16LE(localOffset+26),le=buffer.readUInt16LE(localOffset+28),start=localOffset+30+ln+le,end=start+size;if(end>buffer.length)throw Error('truncated entry');const data=Buffer.from(buffer.subarray(start,end));if(crc32(data)!==crc)throw Error('CRC mismatch: '+name);total+=data.length;if(total>maxBytes)throw Error('archive extracted size exceeds limit');out.push({name,data});pos+=46+nameLen+extraLen+commentLen;}return out;}
export function writeZip(file,entries){fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,createZip(entries));return file;}
export function extractZip(file,dest,opts={}){const entries=readZip(fs.readFileSync(file),opts);const root=path.resolve(dest);for(const e of entries){const target=path.resolve(root,e.name);if(target!==root&&!target.startsWith(root+path.sep))throw Error('archive path traversal');fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,e.data,{mode:0o600});}return entries.map(x=>x.name);}
